import { DevicePicker, deviceById, deviceSilhouette } from "march/ui"

// telefon rafı: yalnız telefonlar, aramasız; seçilen telefonun silüeti ve ekranı büyük gösterilir
export function PhoneShelf() {
  let $id = "pixel-8"
  return <div sx={{ flex: ["row", "wrap"], gap: 4 }}>
    <DevicePicker value={$id} onChange={(v: string) => ($id = v)} group="phone" search={false} create={false} label="Telefonlar" />
    <div class="m-card" sx={{ flex: ["col", "center"], gap: 2, p: 5 }}>
      {() => { const d = deviceById($id); return d ? [deviceSilhouette(d), <span sx={{ text: ["lg", "bold"] }}>{d.name}</span>, <span sx={{ text: "sm", color: "muted" }}>{`${d.width} × ${d.height} CSS piksel · ${d.dpr}x`}</span>] : "Bir telefon seç" }}
    </div>
  </div>
}

import { signal } from "march"
import { DevicePicker, DevicePreview, Popover, Button, deviceById } from "march/ui"

// gerçek hayattan: tasarım gözden geçirme; araç çubuğundaki düğme seçiciyi açar, sayfa seçilen cihazda (dikey ya da
// yatay) çizilir; "Panele sığdır" cihazsız gösterir
export function ResponsiveReview() {
  const device = signal("iphone-15")
  const land = signal(false)
  const page = () => <div sx={{ flex: "col", gap: 2, p: 4 }}>
    <span sx={{ text: ["xl", "bold"] }}>HADİ etkinlikleri</span>
    <span sx={{ text: "sm", color: "muted" }}>Bu hafta 12 buluşma var</span>
  </div>
  return <div sx={{ flex: "col", gap: 3 }}>
    <Popover placement="bottom-start" trigger={<Button size="sm" variant="secondary">{() => deviceById(device())?.name ?? "Panele sığdır"}</Button>}>
      <DevicePicker value={device} landscape={land} fit />
    </Popover>
    {() => (deviceById(device()) ? <DevicePreview device={device} landscape={land} controls fitHeight={460}>{page()}</DevicePreview> : <div class="m-card">{page()}</div>)}
  </div>
}

import { signal } from "march"
import { DevicePicker, DEVICES } from "march/ui"

// DevicePicker'ın bütün özellikleri: value (sinyal), onChange, landscape, fit (kendi metniyle), devices (kendi
// listen), group, search, create, label, class
const kiosk = { id: "lobby", name: "Lobi kiosku", width: 1080, height: 1920, kind: "screen" as const, radius: 0, touch: true }
const LIST = [DEVICES["iphone-se"], DEVICES["pixel-8"], DEVICES["ipad"], DEVICES["desktop-1920"], kiosk]

export function DevicePickerLab() {
  const device = signal("pixel-8")
  const land = signal(false)
  let $picked = "pixel-8"
  return <div sx={{ flex: "col", gap: 3 }}>
    <DevicePicker class="lab-picker" value={device} onChange={(v: string) => ($picked = v || "sığdır")} landscape={land}
      fit="Tam ekran" devices={LIST} group="all" search create={false} label="Test cihazları" />
    <span class="lab-picked" sx={{ text: "sm", color: "muted" }}>{() => `Seçilen: ${$picked} · ${land() ? "yatay" : "dikey"}`}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DevicePickerLab } from "./DevicePickerLab.tsx"

// DevicePickerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kendi listesi: beş cihaz ve en başta kendi metniyle sığdır", () => {
  const s = renderTest(() => <DevicePickerLab />)
  const rows = s.all(".lab-picker .m-dpick-item")
  expect(rows.length).toBe(6)
  expect(rows[0]?.textContent).toContain("Tam ekran")
  expect(s.sees("Lobi kiosku")).toBe(true)
})

test("bir cihaza basınca seçilir", () => {
  const s = renderTest(() => <DevicePickerLab />)
  const ipad = s.all(".lab-picker .m-dpick-item").find((r: Element) => r.textContent?.startsWith("iPad")) as HTMLElement | undefined
  ipad?.click()
  expect(s.get(".lab-picked")?.textContent).toContain("ipad")
})

test("Yatay seçilince boyutlar yer değiştirir", () => {
  const s = renderTest(() => <DevicePickerLab />)
  expect(s.sees("820 × 1180")).toBe(true)
  // önizlemenin diline göre "Yatay" ya da "Landscape"
  const land = s.all("button").find((b: Element) => /^(Yatay|Landscape)$/.test(b.textContent?.trim() ?? "")) as HTMLElement | undefined
  land?.click()
  expect(s.sees("1180 × 820")).toBe(true)
  expect(s.get(".lab-picked")?.textContent).toContain("yatay")
})
